const CUTOFF_TIME = '5:00 PM';   // change here if you agree a different deadline time

const tasks = $('Get Onboarding Tasks')
  .all()
  .map(i => i.json)
  .filter(t => t.task_id);

const customers = $('Get Customers')
  .all()
  .map(i => i.json)
  .filter(c => c.customer_id);

const followupLogs = $('Get Follow-Up Log')
  .all()
  .map(i => i.json)
  .filter(log => log.followup_id && log.task_id);

const now = new Date();

const lagosDate = date => new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Africa/Lagos',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(date);

const today = lagosDate(now);

const tomorrowDate = new Date(`${today}T12:00:00Z`);
tomorrowDate.setUTCDate(tomorrowDate.getUTCDate() + 1);
const tomorrow = tomorrowDate.toISOString().slice(0, 10);

function getDateOnly(value) {
  if (!value) return null;
  const text = String(value).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(text)) return text.slice(0, 10);
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return null;
  return lagosDate(parsed);
}

const customerMap = new Map();
for (const customer of customers) {
  customerMap.set(String(customer.customer_id), customer);
}

// Tasks already reminded today (Lagos date). FAILED rows do not count.
const remindedTodayTaskIds = new Set();
for (const log of followupLogs) {
  if (String(log.status || '').toUpperCase() !== 'SENT' || !log.sent_at) continue;
  if (getDateOnly(log.sent_at) === today) {
    remindedTodayTaskIds.add(String(log.task_id));
  }
}

// Stage: OVERDUE > DUE_TODAY > DUE_TOMORROW
const stageRank = { DUE_TOMORROW: 1, DUE_TODAY: 2, OVERDUE: 3 };

const dueTasksByCustomer = new Map();

for (const task of tasks) {
  const status = String(task.status || '').trim().toUpperCase();
  if (!['PENDING', 'IN_PROGRESS'].includes(status)) continue;

  // Only remind customers about tasks that are theirs to complete
  if (String(task.responsible_party || '').trim().toUpperCase() !== 'CUSTOMER') continue;

  const dueDate = getDateOnly(task.due_date);
  if (!dueDate || dueDate > tomorrow) continue;

  const taskId = String(task.task_id);
  if (remindedTodayTaskIds.has(taskId)) continue;

  const customerId = String(task.customer_id);
  const customer = customerMap.get(customerId);
  if (!customer || !customer.email) continue;

  const stage =
    dueDate < today ? 'OVERDUE' :
    dueDate === today ? 'DUE_TODAY' :
    'DUE_TOMORROW';

  if (!dueTasksByCustomer.has(customerId)) {
    dueTasksByCustomer.set(customerId, {
      customer_id: customerId,
      business_name: customer.business_name,
      contact_name: customer.contact_name,
      email: customer.email,
      tasks: []
    });
  }

  dueTasksByCustomer.get(customerId).tasks.push({
    task_id: taskId,
    task_title: task.task_title,
    task_description: task.task_description,
    due_date: dueDate,
    status,
    stage
  });
}

const dueLine = task =>
  task.stage === 'OVERDUE'      ? `Overdue - it was due on ${task.due_date}` :
  task.stage === 'DUE_TODAY'    ? `Due today by ${CUTOFF_TIME}` :
                                  `Due tomorrow (${task.due_date}) by ${CUTOFF_TIME}`;

const results = [];

for (const customer of dueTasksByCustomer.values()) {
  const topStage = customer.tasks
    .map(t => t.stage)
    .sort((a, b) => stageRank[b] - stageRank[a])[0];

  const subjectTag =
    topStage === 'OVERDUE' ? 'Overdue' :
    topStage === 'DUE_TODAY' ? 'Due today' :
    'Due tomorrow';

  const taskList = customer.tasks.map((task, index) =>
    `${index + 1}. ${task.task_title}
${task.task_description}
${dueLine(task)}`
  ).join('\n\n');

  results.push({
    json: {
      customer_id: customer.customer_id,
      business_name: customer.business_name,
      contact_name: customer.contact_name,
      email: customer.email,
      email_subject: `Onboarding Reminder (${subjectTag}) - ${customer.business_name}`,
      email_body: `
Hello ${customer.contact_name},

This is a friendly reminder about your onboarding tasks for ${customer.business_name}.

${taskList}

If you have already completed a task, please let our onboarding team know.

Kind regards,
Customer Onboarding Team

Independent onboarding prototype.
      `.trim(),
      tasks: customer.tasks
    }
  });
}

return results;

const stamp = () => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false
}).format(new Date());   // e.g. 2026-11-23 09:10 (Lagos time)

// Log one row per task, using what Gmail actually did (SENT or FAILED).
// FAILED rows do not block tomorrow's retry (only SENT rows suppress a reminder).
const reminders = $('Prepare Follow Up').all();
const results = $input.all();
const uniq = Date.now();
const rows = [];

results.forEach((res, idx) => {
  const pairedIdx = typeof res.pairedItem?.item === 'number' ? res.pairedItem.item : idx;
  const reminder = reminders[pairedIdx]?.json;

  if (!reminder || !reminder.customer_id || !Array.isArray(reminder.tasks)) return;

  const sent = Boolean(res.json && res.json.id);
  const errorText = String(res.json?.error?.message || res.json?.error || 'unknown error').slice(0, 200);

  for (const task of reminder.tasks) {
    rows.push({
      json: {
        followup_id: `${reminder.customer_id}-${task.task_id}-${uniq}`,
        customer_id: reminder.customer_id,
        task_id: task.task_id,
        sent_at: stamp(),
        channel: 'EMAIL',
        message: sent
          ? `Reminder sent for task: ${task.task_title}`
          : `Reminder FAILED for task: ${task.task_title} (${errorText})`,
        status: sent ? 'SENT' : 'FAILED'
      }
    });
  }
});

return rows;
